"const fs = require('fs');
const path = require('path');

const pagesDir = path.join(__dirname, '../petcare-react/src/pages');
const files = fs.readdirSync(pagesDir).filter(f => f.endsWith('.jsx'));

files.forEach(file => {
  const filePath = path.join(pagesDir, file);
  let content = fs.readFileSync(filePath, 'utf8');

  // Look for if (!something) return null;\n\n    <main
  // Or just look for an un-returned <main that starts exactly with 4 spaces.

  // A safe regex: find `\n\n    <main className="` and replace with `\n\n  return (\n    <main className="`
  // But wait, what if it's already returned?
  // Let's check if it doesn't have `return (` immediately preceding it.

  // We can just use a regex that matches the exact missing pattern
  // E.g., replacing `\n    <main className="p-4 md:p-8 pb-24 md:pb-8`
  // But let's verify if `return (` is missing.

  const targetPattern1 = /\n    <main className="p-4 md:p-8 pb-24 md:pb-8 flex flex-col/g;
  if (targetPattern1.test(content) && !content.includes('return (\n    <main className="p-4')) {
    content = content.replace(targetPattern1, '\n  return (\n    <main className="p-4 md:p-8 pb-24 md:pb-8 flex flex-col');
    fs.writeFileSync(filePath, content, 'utf8');
    console.log(`Fixed ${file}`);
  }

  const targetPattern2 = /\n    <main className="p-4 md:p-8 pb-24 md:pb-8 flex flex-col items-center justify-center/g;
  if (targetPattern2.test(content) && !content.includes('return (\n    <main className="p-4')) {
    content = content.replace(targetPattern2, '\n  return (\n    <main className="p-4 md:p-8 pb-24 md:pb-8 flex flex-col items-center justify-center');
    fs.writeFileSync(filePath, content, 'utf8');
    console.log(`Fixed ${file} (pattern 2)`);
  }
});
"

